using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.LoyaltyDiscount;

public sealed class CalculateLoyaltyDiscountRulesAcceptanceTests
{
    [Theory]
    [InlineData(20_000, LoyaltyTier.Gold, 2_000, 18_000)]
    [InlineData(30_000, LoyaltyTier.Silver, 2_000, 28_000)]
    [InlineData(12_000, LoyaltyTier.Gold, 1_800, 10_200)]
    public void S2_LoyaltyDiscountNeverExceedsTwentyEuros(
        int subtotalCents, LoyaltyTier tier, int expectedDiscountCents, int expectedTotalCents) =>
        AssertQuote(subtotalCents, tier, null, expectedDiscountCents, expectedTotalCents);

    [Theory]
    [InlineData(2_999, 0, 2_999)]
    [InlineData(3_000, 450, 2_550)]
    public void S3_NoLoyaltyDiscountUnderThirtyEurosSubtotal(
        int subtotalCents, int expectedDiscountCents, int expectedTotalCents) =>
        AssertQuote(subtotalCents, LoyaltyTier.Gold, null, expectedDiscountCents, expectedTotalCents);

    [Theory]
    [InlineData(10_000, LoyaltyTier.Silver, 1_500, 8_500)]
    [InlineData(2_000, LoyaltyTier.Bronze, 500, 1_500)]
    public void S4_Welcome5TakesFiveEurosOffAfterTheLoyaltyDiscount(
        int subtotalCents, LoyaltyTier tier, int expectedDiscountCents, int expectedTotalCents) =>
        AssertQuote(subtotalCents, tier, "WELCOME5", expectedDiscountCents, expectedTotalCents);

    [Theory]
    [InlineData(20_000, LoyaltyTier.Gold, 2_500, 17_500)]
    [InlineData(30_000, LoyaltyTier.Silver, 2_500, 27_500)]
    public void S5_CapAppliesToTheLoyaltyDiscountOnlyNeverToWelcome5(
        int subtotalCents, LoyaltyTier tier, int expectedDiscountCents, int expectedTotalCents) =>
        AssertQuote(subtotalCents, tier, "WELCOME5", expectedDiscountCents, expectedTotalCents);

    [Theory]
    [InlineData("welcome5")]
    [InlineData("Welcome5")]
    public void S6_PromoCodesIgnoreCase(string code) =>
        Assert.Equal(1_500, Quote(10_000, LoyaltyTier.Silver, code).DiscountCents);

    [Theory]
    [InlineData(10_000, LoyaltyTier.Silver, 1_900, 8_100)]
    [InlineData(30_000, LoyaltyTier.Bronze, 3_000, 27_000)]
    [InlineData(2_000, LoyaltyTier.Gold, 200, 1_800)]
    public void S7_Summer10TakesTenPercentOffWhatIsLeftAtMostFifteenEuros(
        int subtotalCents, LoyaltyTier tier, int expectedDiscountCents, int expectedTotalCents) =>
        AssertQuote(subtotalCents, tier, "SUMMER10", expectedDiscountCents, expectedTotalCents);

    [Fact]
    public void S8_UnknownPromoCodeIsIgnored() =>
        AssertQuote(10_000, LoyaltyTier.Silver, "SPRING", 1_000, 9_000);

    [Theory]
    [InlineData(10_000, 2_000, 8_000)]
    [InlineData(5_000, 1_000, 4_000)]
    [InlineData(20_000, 2_000, 18_000)]
    public void S9_PlatinumMembersReceiveTwentyPercentLoyaltyDiscount(
        int subtotalCents, int expectedDiscountCents, int expectedTotalCents) =>
        AssertQuote(subtotalCents, LoyaltyTier.Platinum, null, expectedDiscountCents, expectedTotalCents);

    [Theory]
    [InlineData(400, LoyaltyTier.Bronze, 400)]
    [InlineData(300, LoyaltyTier.Gold, 300)]
    public void S10_DiscountNeverExceedsTheSubtotal(
        int subtotalCents, LoyaltyTier tier, int expectedDiscountCents) =>
        AssertQuote(subtotalCents, tier, "WELCOME5", expectedDiscountCents, 0);

    private static void AssertQuote(
        int subtotalCents, LoyaltyTier tier, string? code, int expectedDiscountCents, int expectedTotalCents) =>
        Assert.Equal(
            new LoyaltyDiscountQuote(subtotalCents, expectedDiscountCents, expectedTotalCents, tier),
            Quote(subtotalCents, tier, code));

    private static LoyaltyDiscountQuote Quote(int subtotalCents, LoyaltyTier tier, string? code) =>
        new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier, code));
}

using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Shipping;

public sealed class CalculateShippingFeeAcceptanceTests
{
    [Theory]
    [InlineData(4_999, LoyaltyTier.Bronze, 490)]
    [InlineData(5_000, LoyaltyTier.Bronze, 0)]
    [InlineData(4_999, LoyaltyTier.Silver, 490)]
    public void S11_StandardShippingIsFreeFromFiftyEurosPayable(
        int payableCents, LoyaltyTier tier, int expectedFeeCents) =>
        Assert.Equal(expectedFeeCents, Fee(payableCents, tier, express: false));

    [Theory]
    [InlineData(LoyaltyTier.Gold)]
    [InlineData(LoyaltyTier.Platinum)]
    public void S12_GoldAndPlatinumMembersNeverPayStandardShipping(LoyaltyTier tier) =>
        Assert.Equal(0, Fee(1_000, tier, express: false));

    [Theory]
    [InlineData(10_000, LoyaltyTier.Bronze, 990)]
    [InlineData(1_000, LoyaltyTier.Gold, 990)]
    [InlineData(1_000, LoyaltyTier.Platinum, 0)]
    public void S13_ExpressShippingCostsNinetyNineHundredthsFreeForPlatinumOnly(
        int payableCents, LoyaltyTier tier, int expectedFeeCents) =>
        Assert.Equal(expectedFeeCents, Fee(payableCents, tier, express: true));

    private static int Fee(int payableCents, LoyaltyTier tier, bool express) =>
        new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(payableCents, tier, express));
}

using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Shipping;

public sealed class QuoteCheckoutAcceptanceTests
{
    [Theory]
    [InlineData(10_000, LoyaltyTier.Silver, "WELCOME5", false, 8_500, 0, 8_500)]
    [InlineData(5_000, LoyaltyTier.Bronze, null, false, 4_750, 490, 5_240)]
    [InlineData(20_000, LoyaltyTier.Platinum, "SUMMER10", true, 16_500, 0, 16_500)]
    [InlineData(2_000, LoyaltyTier.Gold, null, true, 2_000, 990, 2_990)]
    public void S14_CheckoutQuoteAddsShippingToThePayableTotal(
        int subtotalCents, LoyaltyTier tier, string? code, bool express,
        int expectedPayableCents, int expectedShippingCents, int expectedTotalCents)
    {
        var quote = new QuoteCheckout().Handle(new QuoteCheckoutQuery(subtotalCents, tier, code, express));

        Assert.Equal(new CheckoutQuote(expectedPayableCents, expectedShippingCents, expectedTotalCents), quote);
    }
}

using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculateShippingFeeQuery(int PayableTotalCents, LoyaltyTier LoyaltyTier, bool Express = false);

public sealed class CalculateShippingFee
{
    public int Handle(CalculateShippingFeeQuery query) => 0;
}

using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record QuoteCheckoutQuery(int SubtotalCents, LoyaltyTier LoyaltyTier, string? PromoCode, bool Express);

public sealed record CheckoutQuote(int PayableCents, int ShippingCents, int TotalCents);

public sealed class QuoteCheckout
{
    public CheckoutQuote Handle(QuoteCheckoutQuery query) => new(0, 0, 0);
}

